/**
 * Reference QR matrices, generated once by a library this repo does not depend on.
 *
 * GENERATED BY, exactly once, outside the repo (a scratch directory, its own package.json;
 * nothing was added to any package.json or to pnpm-lock.yaml here):
 *
 *     npm install qrcode@1.5.4
 *     QRCode.create([{ data: text, mode: 'byte' }], { errorCorrectionLevel: level })
 *
 * `mode: 'byte'` is not optional: node-qrcode's default is automatic segment optimisation, and
 * it would encode `HELLO WORLD` in alphanumeric mode, which `encodeQr` cannot produce and does
 * not claim to. The matrix is read from `qr.modules.data`, row-major, with the version from
 * `qr.version` and the mask from `qr.maskPattern`.
 *
 * These are compared exactly: every module, plus the version and the mask. The mask matters
 * because it is the part of encoding that is a decision rather than a derivation, and a matrix
 * that agrees on the modules but not the mask means the penalty scoring drifted.
 *
 * ONE KNOWN DISAGREEMENT WITH THIS REFERENCE, measured before these fixtures were taken. Over
 * 600 randomised payloads (1 to 300 characters over an alphabet including multi-byte UTF-8,
 * across all four error-correction levels, versions 1 to 18), `encodeQr` reproduced 591 of
 * node-qrcode's matrices module for module. The 9 that differed differed only in the mask, and
 * every one of them traces to node-qrcode's `getPenaltyN4`, which scores the dark-module balance
 * as `|ceil(percent / 5) - 10|`. That charges a symbol 10 points for a dark proportion between
 * 50 % and 55 %, where ISO/IEC 18004 table 24 puts the whole band 50 % to 55 % at k = 0. In all
 * 9, `encodeQr`'s mask scored strictly lower under the specification's own rule (for example
 * 736 against 740, and 419 against 420). `encode.ts` follows the specification, which is also
 * what ZXing does; the seven payloads below are all in the agreeing majority, which is why they
 * can be pinned this exactly.
 *
 * Every fixture was also rendered to a PNG through `@kelpi/core/icon/png` and decoded back to
 * its payload with zxing-cpp 3.1.1, so these matrices are known to be readable and not merely
 * self-consistent. That decoder is not a dependency either, and no test here shells out to it:
 * nothing on this machine has a decoder installed system-wide, so the round trip is recorded in
 * the pull request rather than run in the suite.
 */

import type { QrEcLevel } from './encode.js';

export interface QrReferenceFixture {
    /** Test name, and the label a failure prints. */
    readonly id: string;
    /** The exact payload that was encoded. */
    readonly text: string;
    readonly ecLevel: QrEcLevel;
    /** UTF-8 bytes of `text`, recorded so a fixture cannot silently change payload. */
    readonly byteLength: number;
    /** The version the reference chose. */
    readonly version: number;
    /** The mask the reference's penalty scoring chose. */
    readonly mask: number;
    /** One string per row, top to bottom, '1' dark and '0' light. No quiet zone. */
    readonly rows: readonly string[];
}

